using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for Person – kind: {personInfo.Kind}");

// Round-trip using the typed metadata
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Person? p = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Round-tripped: {p}");

// 2) Probe without throwing: TryGetTypeInfo returns false when metadata is unavailable
//    Use a resolver that only knows about Person (not about Order).
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Artificially block Order so it appears unsupported
            if (ti.Type == typeof(Order))
                throw new NotSupportedException();
        })
};

// TryGetTypeInfo won't throw – it returns false if resolution fails
bool hasPerson = limitedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? pi);
bool hasOrder  = limitedOptions.TryGetTypeInfo(typeof(Order),  out JsonTypeInfo? oi);

Console.WriteLine($"\nTryGetTypeInfo(Person): {hasPerson} → {pi?.Type.Name ?? "(null)"}");
Console.WriteLine($"TryGetTypeInfo(Order):  {hasOrder} → {oi?.Type.Name ?? "(null)"}");

// Records used in the demo
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

